<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {localFetch,readJson} from './http'
import {vRememberDisclosure} from './rememberDisclosure'
import {downloadCsv,sectorCsv} from './forwardPeExport'
import {selectSectors} from './forwardPeSectors'
import type {SectorReport} from './forwardPeSectors'
const props=defineProps<{initial?:SectorReport;compact?:boolean;managed?:boolean}>()
const emit=defineEmits<{sector:[name:string]}>()
const data=ref<SectorReport|null>(props.initial||null),busy=ref(false),error=ref(''),selectedDate=ref(''),sort=ref('amount'),quality=ref('standard'),parent=ref(''),search=ref('')
const dialog=ref<HTMLDialogElement|null>(null)
let alive=true,epoch=0
const fmt=(n:number|null|undefined,d=2)=>n==null?'—':n.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const signed=(n:number|null|undefined,d=2)=>n==null?'—':`${n>0?'+':''}${fmt(n,d)}`
const pct=(n:number|null|undefined)=>n==null?'—':signed(n)+'%'
const tone=(n:number|null|undefined)=>n==null||n===0?'neutral':n>0?'gain':'loss'
const money=(n:number|null|undefined)=>n==null?'—':n>=1e8?fmt(n/1e8)+' 億':n>=1e4?fmt(n/1e4)+' 萬':fmt(n,0)+' 元'
const parents=computed(()=>[...new Set(data.value?.rows.map(r=>r.parent)||[])].sort())
const rows=computed(()=>selectSectors(data.value?.rows||[],{sort:sort.value,quality:quality.value,parent:parent.value,search:search.value}))
async function load(){
 const call=++epoch;busy.value=true;error.value=''
 try{const r=await localFetch('/api/forward-pe/sectors'+(selectedDate.value?'?'+new URLSearchParams({date:selectedDate.value}):'')),j=await readJson(r);if(!r.ok)throw Error(j.error||'族群資料讀取失敗');if(alive&&call===epoch)data.value=j}catch(e){if(alive&&call===epoch)error.value=(e as Error).message}finally{if(alive&&call===epoch)busy.value=false}
}
function openGroup(name:string){dialog.value?.close();emit('sector',name)}
function openAll(){dialog.value?.showModal()}
watch(()=>props.initial,v=>{epoch++;busy.value=false;error.value='';selectedDate.value='';data.value=v||null})
onMounted(()=>{if(!props.initial&&!props.managed)load()});onUnmounted(()=>{alive=false;epoch++})
defineExpose({reload:()=>{selectedDate.value='';return load()}})
</script>
<template>
 <section class="sector-panel" :class="{compact}" aria-label="自訂族群每日漲跌">
  <header><div><h2>類股漲跌</h2><small>自訂族群 · {{data?.classification.groups||0}} 組</small></div><button v-if="!compact" :disabled="busy" @click="load">{{busy?'讀取中':'讀取已保存資料'}}</button></header>
  <div class="saved-date"><b>{{data?.date||'尚無收盤資料'}}</b><span>前日 {{data?.previous_date||'未核對'}}</span></div>
  <div class="sort-tabs" role="group" aria-label="族群排序"><button v-for="s in [{id:'amount',label:'成交額'},{id:'rising',label:'漲幅'},{id:'falling',label:'跌幅'}]" :key="s.id" :aria-pressed="sort===s.id" @click="sort=s.id">{{s.label}}</button></div>
  <p v-if="error" class="warning" role="alert">{{error}}</p><p v-if="busy&&!data" class="empty">讀取已保存的族群收盤…</p>
  <p v-for="w in data?.warnings" :key="w" class="warning" role="status">{{w}}</p>
  <div v-if="data" class="compact-list" tabindex="0" aria-label="族群簡表，可上下捲動"><article v-for="r in rows.slice(0,compact?8:12)" :key="r.name"><button class="group-name" @click="openGroup(r.name)">{{r.name}}<small>{{r.parent}} · {{r.quoted}}／{{r.members}} 檔有兩日價格</small></button><div class="row-values"><strong :class="tone(r.return_pct)">{{pct(r.return_pct)}}</strong><span>{{money(r.amount_twd)}}<small v-if="!r.amount_complete">部分金額 {{r.amount_names}}／{{r.members}}檔</small></span></div><div class="share"><span>成交比重 {{r.amount_share_pct==null?'—':fmt(r.amount_share_pct)+'%'}}</span><small v-if="r.share_change_pp!=null">較前日 {{signed(r.share_change_pp)}} 百分點</small><small v-else>比重變化資料未齊</small></div></article><p v-if="!rows.length" class="empty">沒有符合條件的族群。可在完整清單改看全部或補齊行情。</p></div>
  <footer><button class="all-button" @click="openAll">全部族群與前日比較 <span>↗</span></button><small>{{quality==='standard'?'至少3檔、價格涵蓋80%':'已選全部族群（含缺價）'}}。{{rows.length}}／{{data?.classification.groups||0}}組符合。<br>等權未還原漲跌，非官方產業指數。多重歸類，比重不可相加。</small></footer>
  <dialog ref="dialog" class="sector-dialog" @click="($event.target===dialog)&&dialog?.close()">
   <div class="dialog-heading"><div><small>OUR SECTOR GROUPS · SAVED CLOSE</small><h2>自訂族群漲跌與成交集中度</h2><p>成交比重增加只代表交易集中，不等於淨買入。</p></div><button aria-label="關閉族群清單" @click="dialog?.close()">✕</button></div>
   <div class="filters"><label>收盤日期<select v-model="selectedDate" :disabled="busy" @change="load"><option value="">最新保存{{data?.dates[0]?' · '+data.dates[0]:''}}</option><option v-for="d in data?.dates" :key="d" :value="d">{{d}}</option></select></label><label>排序<select v-model="sort"><option value="amount">成交金額高到低</option><option value="rising">漲幅高到低</option><option value="falling">跌幅大到小</option></select></label><label>篩選<select v-model="quality"><option value="standard">至少3檔、價格涵蓋80%</option><option value="all">全部，含小族群及缺價</option></select></label><label>大類<select v-model="parent"><option value="">全部大類</option><option v-for="p in parents" :key="p">{{p}}</option></select></label><input v-model="search" type="search" aria-label="搜尋族群" placeholder="搜尋族群或大類"/></div>
   <div class="dialog-summary"><button :disabled="!data||busy" @click="data&&downloadCsv(sectorCsv(data,rows),`自訂族群-${data.date}.csv`)">匯出目前清單 CSV</button><span>{{data?.date||'尚無資料'}} 比較 {{data?.previous_date||'前日未核對'}} · {{rows.length}}／{{data?.classification.groups||0}} 組</span><span>四碼股票總成交 {{money(data?.market_turnover_twd)}} · {{data?.market_names||0}} 檔</span></div>
   <p v-if="error" class="warning">{{error}}</p><p v-for="w in data?.warnings" :key="w" class="warning">{{w}}</p>
   <p class="scroll-hint">左右滑動表格，可查看成交金額、前日比重與比重變化。</p>
   <div class="sector-table-scroll" tabindex="0" aria-label="自訂族群比較表，可上下左右捲動"><table><thead><tr><th>族群／大類</th><th>等權漲跌</th><th>成交金額</th><th>當日比重</th><th>前日比重</th><th>比重變化</th><th>涵蓋檔數</th></tr></thead><tbody><tr v-for="r in rows" :key="r.name"><th><button class="group-name" @click="openGroup(r.name)">{{r.name}}</button><small>{{r.parent}}</small></th><td :class="tone(r.return_pct)"><b>{{pct(r.return_pct)}}</b><small>漲{{r.advancers}}／跌{{r.decliners}}／平{{r.unchanged}}</small></td><td>{{money(r.amount_twd)}}<small v-if="!r.amount_complete" class="partial">已知部分金額</small></td><td>{{r.amount_share_pct==null?'—':fmt(r.amount_share_pct)+'%'}}</td><td>{{r.previous_amount_share_pct==null?'—':fmt(r.previous_amount_share_pct)+'%'}}</td><td>{{r.share_change_pp==null?'—':signed(r.share_change_pp)+' 百分點'}}</td><td>價格 {{r.quoted}}／{{r.members}}<small>金額 {{r.amount_names}}／{{r.members}}</small></td></tr><tr v-if="!rows.length"><td colspan="7" class="empty">沒有符合條件的族群，請調整篩選或補齊來源。</td></tr></tbody></table></div>
   <details v-remember-disclosure="'forward-pe.sector-method'" class="sector-method"><summary>分類、來源及計算方式</summary><p>分類快照 {{data?.classification.snapshot||'未提供'}}。過去日期套用現有字典，非當時成分還原。</p><p>{{data?.scope}}</p><p v-for="n in data?.notes" :key="n">{{n}}</p></details>
  </dialog>
 </section>
</template>
<style scoped>
.sector-panel{min-width:0;background:#fff;border:1px solid #e0e7da;border-radius:12px;overflow:hidden;color:#456143}.sector-panel header{padding:20px;border-bottom:1px solid #edf0e8;display:flex;justify-content:space-between;gap:12px;align-items:center}.sector-panel h2{font-size:16px;margin:0 0 6px}.sector-panel header small{font-size:10px;color:#8c9a81}.sector-panel button,.sector-panel select,.sector-panel input{font:inherit;font-size:11px;color:#5d7a54;border:1px solid #dce5d6;background:#fff;border-radius:6px;padding:8px 10px}.sector-panel button{cursor:pointer}.sector-panel button:disabled{opacity:.5;cursor:wait}.saved-date{padding:14px 17px 4px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:7px;font-size:10px;color:#88987c}.saved-date b{font-weight:500}.sort-tabs{display:flex;gap:5px;padding:9px 16px}.sort-tabs button{padding:6px 9px;border:0;background:#f2f5ed;flex:1}.sort-tabs button[aria-pressed=true]{background:#587c5f;color:#fff}.compact .compact-list{max-height:510px;overflow:auto}.compact-list article{border-bottom:1px solid #eef1e9;padding:15px 17px}.sector-panel .group-name{display:block;text-align:left;border:0;padding:0;border-radius:0;background:none;color:#4c6b48;font-size:12px;line-height:1.5;font-weight:500;overflow-wrap:anywhere}.group-name small{display:block;color:#98a18e;font-size:9px;line-height:1.6;margin-top:4px;font-weight:400}.row-values{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-top:8px;flex-wrap:wrap;font-variant-numeric:tabular-nums}.row-values strong{font-size:17px;font-weight:500}.row-values>span{font-size:11px;color:#7a8b70}.row-values small{font-size:9px;display:block;margin-top:4px;color:#b19c6a}.share{display:flex;flex-wrap:wrap;gap:5px 10px;justify-content:space-between;margin-top:9px;font-size:9px;color:#89977e;line-height:1.6}.share small{font-size:9px}.sector-panel footer{padding:15px 17px}.all-button{width:100%;display:flex;justify-content:space-between}.sector-panel footer>small{font-size:9px;line-height:1.9;display:block;color:#94a087;margin-top:12px}.gain{color:#c06d62}.loss{color:#4d8b74}.neutral{color:#8e9b83}.warning{background:#fcf6e8;color:#a18b54;font-size:11px;line-height:1.8;padding:10px 14px;margin:10px}.empty{font-size:11px;line-height:1.8;padding:20px;color:#98a18f}.sector-dialog{width:min(1180px,94vw);max-width:94vw;max-height:90vh;padding:0;border:1px solid #dbe4d5;border-radius:14px;box-sizing:border-box;box-shadow:0 20px 100px #18332330;color:#4b6648}.sector-dialog::backdrop{background:#17332466}.dialog-heading{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;padding:23px 25px 15px}.dialog-heading small{font-size:9px;letter-spacing:.12em;color:#93a085}.dialog-heading h2{font-size:21px;margin:9px 0}.dialog-heading p{font-size:11px;color:#8b987f;margin:0}.filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:10px 25px 18px;background:#f8faf5}.filters label{font-size:10px;color:#8d9b80;display:flex;flex-direction:column;gap:7px}.filters input{max-width:190px}.dialog-summary{display:flex;gap:15px;justify-content:space-between;flex-wrap:wrap;font-size:10px;color:#8a987e;padding:14px 25px}.scroll-hint{display:none;font-size:10px;color:#8b997e;padding:0 18px;margin:0 0 10px}.sector-table-scroll{max-height:52vh;overflow:auto;border-top:1px solid #e6ecdf}.sector-dialog table{min-width:870px;width:100%;border-collapse:collapse;font-size:11px;text-align:right;font-variant-numeric:tabular-nums}.sector-dialog th,.sector-dialog td{padding:13px 15px;border-bottom:1px solid #edf1e8;white-space:nowrap}.sector-dialog thead th{font-size:10px;font-weight:500;color:#8c9b7e;background:#f6f8f0;position:sticky;top:0;z-index:1}.sector-dialog th:first-child{max-width:230px;white-space:normal;text-align:left;min-width:150px}.sector-dialog tbody th{font-weight:400}.sector-dialog table small{display:block;font-size:9px;color:#98a18d;margin-top:6px;line-height:1.5}.sector-dialog table small.partial{color:#af9b68}.sector-method{padding:16px 25px;color:#8b997f;font-size:11px}.sector-method summary{cursor:pointer}.sector-method p{font-size:10px;line-height:1.9}.sector-panel :focus-visible{outline:2px solid #7b9b70;outline-offset:3px}@media(max-width:900px){.scroll-hint{display:block}}@media(max-width:600px){.dialog-heading{padding:18px}.dialog-heading h2{font-size:17px}.filters{padding:12px 18px;gap:10px}.filters label{width:calc(50% - 7px)}.filters select{max-width:100%}.filters input{max-width:100%;width:100%}.dialog-summary{padding:13px 18px}.sector-dialog{width:96vw;max-width:96vw}.sector-table-scroll{max-height:48vh}.sector-method{padding:14px 18px}}
</style>
